//! Opt-in generation-phase profiling (issue #489 Phase 0).
//!
//! Enabled by `CODEGRAPH_PROFILE_GEN=1`. The report goes to **stderr only**,
//! so enabling it cannot change generated bytes — the byte-identity canaries
//! stay valid with profiling on.
//!
//! The instrumentation exists to answer one question before any codegen
//! engine change is considered: *what share of a generation run is template
//! render time?* It separates two costs that are easy to conflate —
//! [`tera::Context::from_serialize`] (building a `serde_json::Value` tree
//! from typed generator context) and [`tera::Tera::render`] (walking the
//! parsed template). A typed-token code generator eliminates the first
//! entirely and changes the shape of the second, so both must be measured
//! separately or the comparison is not like-for-like.

use std::collections::BTreeMap;
use std::sync::{Mutex, OnceLock};
use std::time::Duration;

/// True when `CODEGRAPH_PROFILE_GEN` is set to `1` or `true`.
///
/// Read once per process; the value is cached so the hot render path pays a
/// single relaxed load.
pub fn enabled() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| {
        matches!(
            std::env::var("CODEGRAPH_PROFILE_GEN").as_deref(),
            Ok("1") | Ok("true")
        )
    })
}

/// Accumulated cost for one template name.
#[derive(Debug, Default, Clone, Copy)]
struct Acc {
    calls: u64,
    serialize: Duration,
    render: Duration,
}

impl Acc {
    fn total(&self) -> Duration {
        self.serialize + self.render
    }
}

fn rows() -> &'static Mutex<BTreeMap<String, Acc>> {
    static ROWS: OnceLock<Mutex<BTreeMap<String, Acc>>> = OnceLock::new();
    ROWS.get_or_init(|| Mutex::new(BTreeMap::new()))
}

fn run_total() -> &'static Mutex<Duration> {
    static TOTAL: OnceLock<Mutex<Duration>> = OnceLock::new();
    TOTAL.get_or_init(|| Mutex::new(Duration::ZERO))
}

/// Record one template render: context-serialization time and render time.
///
/// A no-op when profiling is off.
pub fn record_render(template: &str, serialize: Duration, render: Duration) {
    if !enabled() {
        return;
    }
    let Ok(mut guard) = rows().lock() else {
        return;
    };
    let acc = guard.entry(template.to_string()).or_default();
    acc.calls += 1;
    acc.serialize += serialize;
    acc.render += render;
}

/// Record the wall clock of the whole generation phase.
pub fn record_run_total(total: Duration) {
    if !enabled() {
        return;
    }
    if let Ok(mut guard) = run_total().lock() {
        *guard = total;
    }
}

fn pct(part: Duration, whole: Duration) -> f64 {
    let whole_ns = whole.as_nanos();
    if whole_ns == 0 {
        return 0.0;
    }
    (part.as_nanos() as f64 / whole_ns as f64) * 100.0
}

fn ms(d: Duration) -> f64 {
    d.as_secs_f64() * 1000.0
}

/// Print the accumulated report to stderr. A no-op when profiling is off.
///
/// `top` bounds the per-template breakdown; the summary lines are always
/// printed.
pub fn report_if_enabled(top: usize) {
    if !enabled() {
        return;
    }
    let wall = run_total().lock().map(|g| *g).unwrap_or(Duration::ZERO);
    let Ok(guard) = rows().lock() else {
        return;
    };

    let mut calls = 0u64;
    let mut serialize = Duration::ZERO;
    let mut render = Duration::ZERO;
    for acc in guard.values() {
        calls += acc.calls;
        serialize += acc.serialize;
        render += acc.render;
    }
    let total = serialize + render;

    eprintln!();
    eprintln!("== codegraph generation profile (CODEGRAPH_PROFILE_GEN=1) ==");
    eprintln!("generation wall clock   : {:>10.2} ms", ms(wall));
    eprintln!(
        "template context builds : {:>10.2} ms  ({:>5.1}% of wall)",
        ms(serialize),
        pct(serialize, wall)
    );
    eprintln!(
        "template render         : {:>10.2} ms  ({:>5.1}% of wall)",
        ms(render),
        pct(render, wall)
    );
    eprintln!(
        "template total          : {:>10.2} ms  ({:>5.1}% of wall)",
        ms(total),
        pct(total, wall)
    );
    eprintln!(
        "files rendered          : {:>10}     ({} distinct templates)",
        calls,
        guard.len()
    );

    let mut ranked: Vec<(&String, &Acc)> = guard.iter().collect();
    ranked.sort_by_key(|a| std::cmp::Reverse(a.1.total()));

    eprintln!();
    eprintln!(
        "{:<44} {:>6} {:>11} {:>11} {:>11}",
        "template", "calls", "build ms", "render ms", "total ms"
    );
    for (name, acc) in ranked.iter().take(top) {
        eprintln!(
            "{:<44} {:>6} {:>11.3} {:>11.3} {:>11.3}",
            truncate(name, 44),
            acc.calls,
            ms(acc.serialize),
            ms(acc.render),
            ms(acc.total())
        );
    }
    if ranked.len() > top {
        let rest_serialize: Duration = ranked.iter().skip(top).map(|(_, a)| a.serialize).sum();
        let rest_render: Duration = ranked.iter().skip(top).map(|(_, a)| a.render).sum();
        eprintln!(
            "{:<44} {:>6} {:>11.3} {:>11.3} {:>11.3}",
            format!("… {} more templates", ranked.len() - top),
            "",
            ms(rest_serialize),
            ms(rest_render),
            ms(rest_serialize + rest_render)
        );
    }
    eprintln!();
}

fn truncate(s: &str, max: usize) -> String {
    if s.chars().count() <= max {
        return s.to_string();
    }
    let head: String = s.chars().take(max.saturating_sub(1)).collect();
    format!("{head}…")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn truncate_keeps_short_names_and_clips_long_ones() {
        assert_eq!(truncate("db/table.tera", 44), "db/table.tera");
        let long = "a".repeat(60);
        let clipped = truncate(&long, 10);
        assert_eq!(clipped.chars().count(), 10);
        assert!(clipped.ends_with('…'));
    }

    #[test]
    fn pct_is_zero_for_zero_denominator() {
        assert_eq!(pct(Duration::from_millis(5), Duration::ZERO), 0.0);
    }

    #[test]
    fn pct_computes_expected_share() {
        let share = pct(Duration::from_millis(25), Duration::from_millis(100));
        assert!((share - 25.0).abs() < 1e-9);
    }

    #[test]
    fn recording_is_inert_when_disabled() {
        // `enabled()` is process-global and normally false in a test run. The
        // test must not depend on the ambient environment — CI or a developer
        // shell may legitimately set `CODEGRAPH_PROFILE_GEN=1`.
        let marker = "test/inert.tera";
        record_render(marker, Duration::from_nanos(1), Duration::from_nanos(1));

        let guard = rows().lock().expect("rows lock");
        if enabled() {
            assert!(
                guard.contains_key(marker),
                "profiling is enabled, so the render must have been recorded"
            );
        } else {
            assert!(
                !guard.contains_key(marker),
                "profiling is disabled, so recording must be a no-op"
            );
        }
    }
}
